/* BURBULI DISPLAY v1.2 HOME ENERGY PHOTO TEST - PB616W / InkView 5.17
 * v0.9 dashboard preserved; new photo-first HOME page toggled by NEXT.
 * Read-only HTTP GET from known Raspberry Pi APIs, without Pi changes:
 *  http://192.168.0.195:5003/api/data
 *  http://192.168.0.195:8082/api/aranet
 * HOME: voltage, calc_soc (estimated only!), pv_power,
 *       load_power + direct_power (12V measured branches only).
 * ARANET: sensor 1004E5 house, 1004E8 outdoor;
 *         temperature, humidity and measurement time.
 *         sensor 3000F8 CO2 (ppm), timestamp; no location label.
 * Missing/stale values => dashes. Never show fake readings.
 * Main clock stays local. Network polling every 120s (first after 2s).
 * Exit: five PAGE_PREV presses within 5s; no app timeout.
 * No state-changing requests and no controller firmware changes.
 */
