/* Extract scalar number from one JSON object; handles JSON numbers and
   quoted numeric strings. Each search is limited to the object's range. */
static int json_double(const char *begin, const char *end,
                       const char *key, double *result) {
    char needle[100]; const char *cur=begin;
    size_t len;
    if(!begin || !end || begin>=end || !result) return 0;
    if(snprintf(needle,sizeof(needle),"\"%s\"",key)>=(int)sizeof(needle)) return 0;
    len=strlen(needle);
    while(cur<end && (cur=strstr(cur,needle))!=NULL && cur<end) {
        const char *p=cur+len, *finish;
        char *stop=NULL;
        int quoted=0;
        double d;
        if(p>=end) return 0;
        while(p<end && isspace((unsigned char)*p)) ++p;
        if(p>=end || *p!=':') { cur+=len; continue; }
        ++p;
        while(p<end && isspace((unsigned char)*p)) ++p;
        if(p<end && *p=='\"') {quoted=1; ++p;}
        if(p>=end) return 0;
        errno=0;
        d=strtod(p,&stop);
        finish=stop;
        if(stop==p || errno==ERANGE || !isfinite(d) || finish>end) return 0;
        if(quoted && (finish>=end || *finish!='\"')) return 0;
        *result=d;
        return 1;
    }
    return 0;
}

static int aranet_sensor(const char *json,const char *id,
                         double *temperature,double *humidity) {
    char needle[24];
    const char *p,*obj,*end;
    double stamp;
    time_t now=time(NULL);
    if(snprintf(needle,sizeof(needle),"\"%s\"",id)>=(int)sizeof(needle)) return 0;
    p=strstr(json,needle);
    if(!p) return 0;
    p+=strlen(needle);
    while(*p && isspace((unsigned char)*p)) ++p;
    if(*p!=':') return 0;
    p++;
    while(*p && isspace((unsigned char)*p)) ++p;
    if(*p!='{') return 0;
    obj=p;
    end=strchr(obj,'}');
    if(!end) return 0;
    if(!json_double(obj,end,"measurements/temperature",temperature) ||
       !json_double(obj,end,"measurements/humidity",humidity) ||
       !json_double(obj,end,"measurements/time",&stamp)) return 0;
    /* PB clock is working and synchronized; 20min max age.
       Future timestamps beyond 2min also are not trusted. */
    if(now < 1600000000 || stamp > (double)now+120 ||
       stamp < (double)now-1200) return 0;
    if(*temperature < -55 || *temperature > 85 ||
       *humidity < 0 || *humidity > 100) return 0;
    return 1;
}

/* Single movable CO2 probe. Do not trust group or name as location.
 * Same freshness rule as other ARANET readings: <=20min, not >2min future.
 * Strings in the /api/aranet response are parsed by json_double(). */
static int aranet_co2(const char *json, double *ppm) {
    const char *p,*obj,*end;
    double stamp=0, value=0;
    time_t now=time(NULL);
    p=strstr(json,"\"3000F8\"");
    if(!p) return 0;
    p+=strlen("\"3000F8\"");
    while(*p && isspace((unsigned char)*p)) ++p;
    if(*p++!=':') return 0;
    while(*p && isspace((unsigned char)*p)) ++p;
    if(*p!='{') return 0;
    obj=p; end=strchr(obj,'}');
    if(!end || !json_double(obj,end,"measurements/co2",&value) ||
       !json_double(obj,end,"measurements/time",&stamp)) return 0;
    if(now<1600000000 || stamp>(double)now+120 ||
       stamp<(double)now-1200 || value<250 || value>10000) return 0;
    *ppm=value;
    return 1;
}

static char *get_api(const char *url) {
    int n=0;
    void *raw=QuickDownload(url,&n,8);
    char *answer;
    if(!raw) return NULL;
    if(n<=0 || n>65535) {free(raw);return NULL;}
    answer=(char*)malloc((size_t)n+1);
    if(answer) { memcpy(answer,raw,(size_t)n);answer[n]='\0'; }
    free(raw);
    return answer;
}

static void read_home(DISPLAY_DATA *d) {
    double soc=0, v=0,pv=0,load=0,direct=0;
    int l_ok, dr_ok;
    char *json=get_api(HOME_URL);
    if(!json) return;
    if(*json!='{' && !strchr(json,'{')) {free(json);return;}
    d->home_received=1;
    d->voltage_ok=json_double(json,json+strlen(json),"voltage",&v) && v>7 && v<17;
    d->soc_ok=json_double(json,json+strlen(json),"calc_soc",&soc) && soc>=0 && soc<=100;
    d->pv_ok=json_double(json,json+strlen(json),"pv_power",&pv) && pv>=0 && pv<=10000;
    l_ok=json_double(json,json+strlen(json),"load_power",&load);
    dr_ok=json_double(json,json+strlen(json),"direct_power",&direct);
    d->load_ok=l_ok && dr_ok && load>=0 && direct>=0 && load+direct<=10000;
    if(d->voltage_ok)d->voltage=v;
    if(d->soc_ok)d->soc=soc;
    if(d->pv_ok)d->pv=pv;
    if(d->load_ok)d->load=load+direct;
    free(json);
}
static void read_aranet(DISPLAY_DATA *d) {
    char *json=get_api(ARANET_URL);
    if(!json) return;
    if(!strstr(json,"\"sensors\"")) {free(json);return;}
    d->aranet_received=1;
    d->inside_ok=aranet_sensor(json,"1004E5",&d->t_inside,&d->h_inside);
    d->outside_ok=aranet_sensor(json,"1004E8",&d->t_outside,&d->h_outside);
    d->co2_ok=aranet_co2(json,&d->co2);
    free(json);
}

static time_t exit_window=0;

/* High-contrast glyphs: independently selectable W and H, no system font or assets. */
static void glyph(char c,int x,int y,int width,int height) {
    int idx=(c=='.')?10:((c>='0' && c<='9')?c-'0':-1);
    if(idx<0) return;
    const GLYPH *g=&glyphs[idx];
    int j;
    for(j=0;j<g->n;j++) {
        const GLYPHRECT *r=&g->rects[j];
        int x0=x+(r->x0*width)/60;
        int x1=x+(r->x1*width+59)/60;
        int y0=y+(r->y0*height)/112;
        int y1=y+(r->y1*height+111)/112;
        if(x1>x0 && y1>y0) FillArea(x0,y0,x1-x0,y1-y0,BLACK);
    }
}
static int number(const char *s,int x,int y,int dw,int dh,int gap) {
    while(*s) {
        if(*s==':') {
            int cw=dw/4, sz=cw;
            FillArea(x+1,y+dh/3,sz,sz,BLACK);
            FillArea(x+1,y+(dh*2)/3,sz,sz,BLACK);
            x+=cw+gap;
        } else if(*s=='.') {
            int dot=dw/4;
            glyph('.',x,y,dot,dh);
            x+=dot+gap/2;
        } else if(*s>='0' && *s<='9') {
            glyph(*s,x,y,dw,dh);
            x+=dw+gap;
        } else if(*s=='-') {
            FillArea(x,y+dh/2-6,dw/2,12,BLACK);
            x+=dw/2+gap;
        } else if(*s==' ') x+=dw/4;
        ++s;
    }
    return x;
}

/* SOC comes ONLY from the Pi calc_soc field, not the invalid
 * EPEver battery_soc. Six segments, rounded to nearest filled block. */
static void round_fill(int x,int y,int w,int h,int radius,int colour) {
    int row;
    for(row=0;row<h;row++) {
        int cap=row,cut=0;
        if(h-1-row<cap) cap=h-1-row;
        if(cap<radius) {
            int yy=radius-1-cap,xx;
            for(xx=radius;xx>=0;xx--) if(xx*xx+yy*yy<=radius*radius) break;
            cut=radius-xx;
        }
        if(w-2*cut>0) FillArea(x+cut,y+row,w-2*cut,1,colour);
    }
}
static void soc_draw_bar(void) {
    int i, filled=0;
    char label[12]="--%";
    if(live_data.soc_ok) {
        filled=(int)(live_data.soc*6.0/100.0+0.5);
        if(filled>6) filled=6;
        snprintf(label,sizeof(label),"%d%%",(int)(live_data.soc+0.5));
    }
    for(i=0;i<6;i++) {
        int x=36+i*92;
        round_fill(x,23,84,48,9,BLACK);
        if(i>=filled) round_fill(x+3,26,78,42,7,WHITE);
    }
    if(f_soc) {SetFont(f_soc,BLACK);DrawString(602,23,label);}
}
