typedef struct { const unsigned char *pixels; int w,h; } ICON;
static const ICON ico_house = {icon_house_bits,84,88};
static const ICON ico_outside = {icon_outside_bits,84,91};
static const ICON ico_battery = {icon_battery_bits,69,57};
static const ICON ico_drop = {icon_drop_bits,32,40};
static const ICON ico_solar = {icon_solar_bits,68,65};
static const ICON ico_plug = {icon_plug_bits,68,68};

static void draw_icon(const ICON *icon,int x,int y) {
    int iy,ix;
    for(iy=0;iy<icon->h;iy++) {
        int start=-1;
        for(ix=0;ix<=icon->w;ix++) {
            int black=0;
            if(ix<icon->w) {
                int pos=iy*icon->w+ix;
                black=(icon->pixels[pos>>3]>>(7-(pos&7)))&1;
            }
            if(black && start<0) start=ix;
            if(!black && start>=0) {
                FillArea(x+start,y+iy,ix-start,1,BLACK);
                start=-1;
            }
        }
    }
}
static void battery_icon(int x,int y){ draw_icon(&ico_battery,x,y); }
static void house_icon(int x,int y){ draw_icon(&ico_house,x,y); }
static void outdoor_icon(int x,int y){ draw_icon(&ico_outside,x,y); }
static void droplet_icon(int x,int y){ draw_icon(&ico_drop,x,y); }
static void solar_icon(int x,int y){ draw_icon(&ico_solar,x,y); }
static void plug_icon(int x,int y){ draw_icon(&ico_plug,x,y); }

static void degree_icon(int x,int y) {
    const int xx[]={7,12,15,15,12,7,2,0};
    const int yy[]={0,2,7,12,16,17,13,7};
    int i,k;
    for(k=0;k<2;k++) for(i=0;i<8;i++) {
        int j=(i+1)%8;
        DrawLine(x+xx[i]+k,y+yy[i],x+xx[j]+k,y+yy[j],BLACK);
    }
}

