static void draw_house_photo(void) {
    int y,x;
    const int x0=60,y0=248;
    /* v1.2: native 640x348 screen dots, no 2x pixel enlargement. */
    for(y=0;y<348;y++) {
        int start=-1;
        for(x=0;x<=640;x++) {
            int black=0;
            if(x<640) {
                int pos=y*640+x;
                black=(house_photo_bits[pos>>3]>>(7-(pos&7)))&1;
            }
            if(black && start<0) start=x;
            if(!black && start>=0) {
                FillArea(x0+start,y0+y,x-start,1,BLACK);
                start=-1;
            }
        }
    }
}

static void divider(void) {
    DrawLine(32,91,725,91,BLACK);
    DrawLine(30,579,728,579,BLACK);
    DrawLine(382,599,382,972,BLACK);
    DrawLine(29,802,368,802,BLACK);
    DrawLine(406,773,729,773,BLACK);
    DrawLine(406,876,729,876,BLACK);
}
/* All primary values are real or dashes; icons/layout from v0.8. */
static void draw_measurements(void) {
    int after;
    char text[24];
    FillArea(28,9,708,79,WHITE);
    FillArea(28,603,704,406,WHITE);
    soc_draw_bar();
    /* Indoor primary temperature and humidity. */
    house_icon(32,636);
    if(live_data.inside_ok) snprintf(text,sizeof(text),"%.1f",live_data.t_inside);
    else strcpy(text,"--");
    after=number(text,125,612,(strlen(text)>5 || text[0]=='-')?42:51,113,4);
    degree_icon(after+3,627);
    if(f_unit) { SetFont(f_unit,BLACK); DrawString(after+25,666,"C"); }
    droplet_icon(175,744);
    if(live_data.inside_ok) snprintf(text,sizeof(text),"%d",(int)(live_data.h_inside+0.5));
    else strcpy(text,"--");
    after=number(text,217,735,30,53,4);
    if(f_humidity) {SetFont(f_humidity,BLACK);DrawString(after+5,742,"%");}

    /* Outdoor temperature and humidity. */
    outdoor_icon(35,823);
    if(live_data.outside_ok) snprintf(text,sizeof(text),"%.1f",live_data.t_outside);
    else strcpy(text,"--");
    after=number(text,128,810,(strlen(text)>5 || text[0]=='-')?42:54,109,4);
    degree_icon(after+1,821);
    if(f_unit) {SetFont(f_unit,BLACK);DrawString(after+20,857,"C");}
    droplet_icon(175,939);
    if(live_data.outside_ok) snprintf(text,sizeof(text),"%d",(int)(live_data.h_outside+0.5));
    else strcpy(text,"--");
    after=number(text,217,931,30,53,4);
    if(f_humidity) {SetFont(f_humidity,BLACK);DrawString(after+5,938,"%");}

    /* House battery voltage (SOC above), PV power and measured 12V load. */
    battery_icon(401,641);
    if(live_data.voltage_ok) snprintf(text,sizeof(text),"%.2f",live_data.voltage);
    else strcpy(text,"--");
    after=number(text,480,619,43,107,4);
    if(f_unit) {SetFont(f_unit,BLACK);DrawString(after+6,671,"V");}

    solar_icon(407,799);
    if(live_data.pv_ok) snprintf(text,sizeof(text),"%d",(int)(live_data.pv+0.5));
    else strcpy(text,"--");
    after=number(text,493,792,(strlen(text)>3)?37:48,75,5);
    if(f_humidity) {SetFont(f_humidity,BLACK);DrawString(after+3,822,"W");}

    plug_icon(414,899);
    if(live_data.load_ok) snprintf(text,sizeof(text),"%d",(int)(live_data.load+0.5));
    else strcpy(text,"--");
    after=number(text,495,886,(strlen(text)>3)?37:49,76,5);
    if(f_humidity) {SetFont(f_humidity,BLACK);DrawString(after+4,919,"W");}

    if(f_small) {
        SetFont(f_small,BLACK);
        /* Distinguish API connection from stale/missing individual fields. */
        {
            const char *home=live_data.home_received ? "HOME OK" : "HOME ?";
            const char *aranet=!live_data.aranet_received ? "ARANET ?" :
                (live_data.inside_ok && live_data.outside_ok ? "ARANET OK" : "ARANET OLD/MISS");
            char status[64];
            snprintf(status,sizeof(status),"%s / %s",home,aranet);
            DrawString(32,115,status);
        }
        DrawString(679,115,"v1.2");
    }
}
/* Photo-first HOME page. Existing v0.9 dashboard is retained as page 2.
 * Only cached/validated live_data are displayed (no fabricated measurements).
 */
static int active_page=0;
static void photo_readings(void) {
    char buf[64];
    FillArea(22,600,714,414,WHITE);
    DrawLine(24,598,731,598,BLACK);
    if(f_day) {SetFont(f_day,BLACK);DrawString(35,630,"ДОМ");}
    if(f_small) {SetFont(f_small,BLACK);DrawString(35,707,"ВНУТРИ");DrawString(393,707,"СНАРУЖИ");}
    if(f_unit) {
        SetFont(f_unit,BLACK);
        if(live_data.inside_ok) snprintf(buf,sizeof(buf),"%.1f C",live_data.t_inside);
        else strcpy(buf,"-- C");
        DrawString(35,750,buf);
        if(live_data.outside_ok) snprintf(buf,sizeof(buf),"%.1f C",live_data.t_outside);
        else strcpy(buf,"-- C");
        DrawString(393,750,buf);
    }
    DrawLine(24,818,731,818,BLACK);
    if(f_small) {
        SetFont(f_small,BLACK);
        /* SOC is shown at top; do not duplicate the same percentage below. */
        if(live_data.co2_ok)
            snprintf(buf,sizeof(buf),"CO2: %.0f ppm",live_data.co2);
        else if(live_data.aranet_received)
            strcpy(buf,"CO2: -- (нет/стар.)");
        else strcpy(buf,"CO2: -- (нет связи)");
        DrawString(35,855,buf);
        /* Dedicated bottom strip with enough space above physical screen edge. */
        DrawLine(28,909,729,909,BLACK);
        DrawString(35,942,"NEXT: приборы  |  PREV x5: выход");
        DrawString(661,974,"v1.2");
    }
}
static void photo_clock(void) {
    char time_text[12]="--:--",date_text[32]="--.--.----";
    time_t now=time(NULL);struct tm *tm=localtime(&now);
    if(tm) {
        strftime(time_text,sizeof(time_text),"%H:%M",tm);
        snprintf(date_text,sizeof(date_text),"%02d.%02d.%04d",tm->tm_mday,tm->tm_mon+1,tm->tm_year+1900);
        last_minute=tm->tm_min;last_day=tm->tm_yday;
    }
    FillArea(24,93,711,150,WHITE);
    number(time_text,42,107,75,113,6);
    if(f_date) {SetFont(f_date,BLACK);DrawString(474,169,date_text);}
    if(f_small) {
        char energy[48],pv[14],cons[14];
        if(live_data.pv_ok) snprintf(pv,sizeof(pv),"%.0f",live_data.pv);
        else strcpy(pv,"--");
        if(live_data.load_ok) snprintf(cons,sizeof(cons),"%.0f",live_data.load);
        else strcpy(cons,"--");
        snprintf(energy,sizeof(energy),"PV %s W / %s W",pv,cons);
        SetFont(f_small,BLACK);
        DrawString(474,219,energy);
    }
    PartialUpdate(24,93,711,150);
}
static void photo_page(void) {
    ClearScreen();
    soc_draw_bar();
    DrawLine(25,90,733,90,BLACK);
    draw_house_photo();
    photo_readings();
    photo_clock();
    FullUpdate();
}

static void draw_page(void) {
    if(active_page==0) {photo_page();return;}
    ClearScreen();
    divider();
    draw_measurements();
}
static void network_poll(void) {
    DISPLAY_DATA next;
    memset(&next,0,sizeof(next));
    read_home(&next);
    read_aranet(&next);
    /* Redraw only when something has changed. No stale cached data. */
    if(memcmp(&next,&live_data,sizeof(next))!=0) {
        live_data=next;
        if(active_page==0) {
            photo_readings();
            /* SOC bar is also live; update only the header and readings. */
            FillArea(28,9,708,79,WHITE); soc_draw_bar();
            /* Refresh energy alongside the date when API values change. */
            photo_clock();
            PartialUpdate(25,8,711,82);PartialUpdate(22,598,714,417);
        } else {
            draw_measurements();
            PartialUpdate(25,12,711,997);
        }
    }
    SetHardTimer("burbuli_v12_net",network_poll,120000);
}
static void clock_render(int full) {
    char time_text[12]="--:--";
    char date_text[30]="--.--.----";
    static const char *weekday[]={
       "ВОСКРЕСЕНЬЕ","ПОНЕДЕЛЬНИК","ВТОРНИК","СРЕДА",
       "ЧЕТВЕРГ","ПЯТНИЦА","СУББОТА"
    };
    time_t now=time(NULL); struct tm *tm=localtime(&now);
    if(tm) {
        strftime(time_text,sizeof(time_text),"%H:%M",tm);
        snprintf(date_text,sizeof(date_text),"%02d.%02d.%04d",
                 tm->tm_mday,tm->tm_mon+1,tm->tm_year+1900);
        last_minute=tm->tm_min;
        last_day=tm->tm_yday;
    }
    if(active_page==0) { photo_clock(); return; }
    /* clock portion only; measurements are refreshed independently */
    FillArea(28,120,701,443,WHITE);
    number(time_text,57,130,139,321,7);
    if(f_date && f_day) {
        SetFont((tm && strlen(weekday[tm->tm_wday])>17)?f_longday:f_day,BLACK);
        DrawString(38,498,tm?weekday[tm->tm_wday]:"ДЕНЬ");
        DrawLine(389,499,389,561,BLACK);
        SetFont(f_date,BLACK);
        DrawString(412,500,date_text);
    }
    if(full) FullUpdate();
    else PartialUpdate(28,120,701,443);
}
static void tick(void) {
    time_t now=time(NULL); struct tm *tm=localtime(&now);
    if(!tm || tm->tm_min!=last_minute || tm->tm_yday!=last_day)
        clock_render((++refresh_count%12)==0);
    SetHardTimer("burbuli_v12_tick",tick,30000);
}
static int handler(int type,int p1,int p2) {
    (void)p2;
    switch(type) {
      case EVT_INIT:
        SetOrientation(0); /* portrait; PocketBook physical buttons BELOW */
        f_day=OpenFont("LiberationSans-Bold",43,0);
        f_longday=OpenFont("LiberationSans-Bold",36,0);
        f_date=OpenFont("LiberationSans-Bold",44,0);
        f_unit=OpenFont("LiberationSans-Bold",47,0);
        f_humidity=OpenFont("LiberationSans-Bold",44,0);
        f_small=OpenFont("LiberationSans",21,0);
        f_soc=OpenFont("LiberationSans-Bold",52,0);
        SetHardTimer("burbuli_v12_tick",tick,30000);
        return 1;
      case EVT_SHOW:
      case EVT_REPAINT:
      case EVT_ORIENTATION:
        draw_page(); clock_render(1);
        if(!network_timer_started) {
            network_timer_started=1;
            SetHardTimer("burbuli_v12_net",network_poll,2000);
        }
        return 1;
      case EVT_KEYDOWN:
        if(p1==IV_KEY_NEXT) {
            active_page=1-active_page;
            exit_count=0;
            draw_page();clock_render(1);
        }
        if(p1==IV_KEY_PREV) {
            time_t now=time(NULL);
            if(exit_count==0 || now-exit_window>5) {
                exit_window=now; exit_count=1;
            } else exit_count++;
            if(exit_count>=5) CloseApp();
        }
        return 1;
      case EVT_KEYUP:
      case EVT_KEYREPEAT: return 1;
      case EVT_EXIT:
        ClearTimerByName("burbuli_v12_tick");
        ClearTimerByName("burbuli_v12_net");
        if(f_day) CloseFont(f_day);
        if(f_longday) CloseFont(f_longday);
        if(f_date) CloseFont(f_date);
        if(f_unit) CloseFont(f_unit);
        if(f_humidity) CloseFont(f_humidity);
        if(f_small) CloseFont(f_small);
        if(f_soc) CloseFont(f_soc);
        return 1;
      default: return 0;
    }
}
int main(int argc,char **argv) {
    (void)argc; (void)argv;
    InkViewMain(handler);
    return 0;
}
